    public static StreamGeometry ForInput(string? input) => input?.ToLowerInvariant() switch
    {
        "bluetooth" => Bluetooth,
        "optical" => Toslink,
        "co-axial" or "coaxial" or "line-in" or "line-in2" or "auxin" => Rca,
        "hdmi" => HdmiPort,
        "phono" => RecordPlayer,
        "pcusb" or "usb" or "udisk" => Usb,
        _ => Music
    };

